import Header from './components/Header'
import './App.css';
import background from './images/bg.jpg'
function App() {
  return (
    <div style={{backgroundColor: '#3C413E'}}>
      <div style={{backgroundImage: `url(${background})`, backgroundRepeat: 'no-repeat', backgroundPosition: 'center', backgroundSize: 'cover', width: '70vw', height: '100vh', borderTopRightRadius: '10%',borderBottomRightRadius: '10%', opacity: 0.3}}>
        <div style={{ position: 'relative', top: 20, right: 100,fontSize: 60, textAlign: 'right', color: '#0F0404', fontWeight: '1.5rem' }}> Connect with Your co-passengers</div>
      </div>
    </div>
  )
}
export default App;
